 69→// setupResumeTestRepo creates a test repository with an initial commit and optional feature branch.
 70→// Returns the repository, worktree, and commit hash. The caller should use t.Chdir(tmpDir).
 71→func setupResumeTestRepo(t *testing.T, tmpDir string, createFeatureBranch bool) (*git.Repository, *git.Worktree, plumbing.Hash) {
 72→	t.Helper()
 73→
 74→	repo, err := git.PlainInit(tmpDir, false)
 75→	if err != nil {
 76→		t.Fatalf("Failed to init repo: %v", err)
 77→	}
 78→
 79→	w, err := repo.Worktree()
 80→	if err != nil {
 81→		t.Fatalf("Failed to get worktree: %v", err)
 82→	}
 83→
 84→	testFile := filepath.Join(tmpDir, "test.txt")
 85→	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
 86→		t.Fatalf("Failed to write test file: %v", err)
 87→	}
 88→	if _, err := w.Add("test.txt"); err != nil {
 89→		t.Fatalf("Failed to add test file: %v", err)
 90→	}
 91→
 92→	commit, err := w.Commit("initial commit", &git.CommitOptions{
 93→		Author: &object.Signature{
 94→			Name:  "Test User",
 95→			Email: "test@example.com",
 96→		},
 97→	})
 98→	if err != nil {
 99→		t.Fatalf("Failed to create initial commit: %v", err)
100→	}
101→
102→	if createFeatureBranch {
103→		featureRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("feature"), commit)
104→		if err := repo.Storer.SetReference(featureRef); err != nil {
105→			t.Fatalf("Failed to create feature branch: %v", err)
106→		}
107→	}
108→
109→	// Ensure entire/checkpoints/v1 branch exists
110→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
111→		t.Fatalf("Failed to create metadata branch: %v", err)
112→	}
113→
114→	return repo, w, commit
115→}
