149→
150→	t.Run("successfully checks out existing branch", func(t *testing.T) {
151→		err := CheckoutBranch(context.Background(), "feature")
152→		if err != nil {
153→			t.Fatalf("CheckoutBranch() error = %v", err)
154→		}
155→
156→		// Verify we're on the feature branch
157→		branch, err := GetCurrentBranch(context.Background())
158→		if err != nil {
159→			t.Fatalf("GetCurrentBranch() error = %v", err)
160→		}
161→		if branch != "feature" {
162→			t.Errorf("After CheckoutBranch(), current branch = %q, want %q", branch, "feature")
163→		}
164→	})
165→
166→	t.Run("returns error for nonexistent branch", func(t *testing.T) {
167→		err := CheckoutBranch(context.Background(), "nonexistent")
168→		if err == nil {
