176→		err := CheckoutBranch(context.Background(), "-b evil")
177→		if err == nil {
178→			t.Fatal("CheckoutBranch() should reject refs starting with '-', got nil")
179→		}
180→		if !strings.Contains(err.Error(), "invalid ref") {
181→			t.Errorf("CheckoutBranch() error = %q, want error containing 'invalid ref'", err.Error())
