293→// createCheckpointOnMetadataBranchFull creates a checkpoint on the entire/checkpoints/v1 branch
294→// with a caller-specified checkpoint ID and timestamp.
295→func createCheckpointOnMetadataBranchFull(t *testing.T, repo *git.Repository, sessionID string, checkpointID id.CheckpointID, createdAt time.Time) id.CheckpointID {
296→	t.Helper()
297→
298→	// Get existing metadata branch or create it
299→	if err := strategy.EnsureMetadataBranch(repo); err != nil {
300→		t.Fatalf("Failed to ensure metadata branch: %v", err)
301→	}
302→
303→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
304→	ref, err := repo.Reference(refName, true)
305→	if err != nil {
306→		t.Fatalf("Failed to get metadata branch ref: %v", err)
307→	}
308→
309→	parentCommit, err := repo.CommitObject(ref.Hash())
310→	if err != nil {
311→		t.Fatalf("Failed to get parent commit: %v", err)
312→	}
313→
314→	// Create metadata content
315→	metadataJSON := fmt.Sprintf(`{
316→  "checkpoint_id": %q,
317→  "session_id": %q,
318→  "created_at": %q
319→}`, checkpointID.String(), sessionID, createdAt.Format(time.RFC3339))
320→
321→	// Create blob for metadata
322→	blob := repo.Storer.NewEncodedObject()
323→	blob.SetType(plumbing.BlobObject)
324→	writer, err := blob.Writer()
325→	if err != nil {
326→		t.Fatalf("Failed to create blob writer: %v", err)
327→	}
328→	if _, err := writer.Write([]byte(metadataJSON)); err != nil {
329→		t.Fatalf("Failed to write blob: %v", err)
330→	}
331→	if err := writer.Close(); err != nil {
332→		t.Fatalf("Failed to close writer: %v", err)
333→	}
334→	metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
335→	if err != nil {
336→		t.Fatalf("Failed to store blob: %v", err)
337→	}
338→
339→	// Create session log blob
340→	logBlob := repo.Storer.NewEncodedObject()
341→	logBlob.SetType(plumbing.BlobObject)
342→	logWriter, err := logBlob.Writer()
343→	if err != nil {
344→		t.Fatalf("Failed to create log blob writer: %v", err)
345→	}
346→	if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
347→		t.Fatalf("Failed to write log blob: %v", err)
348→	}
349→	if err := logWriter.Close(); err != nil {
350→		t.Fatalf("Failed to close log writer: %v", err)
351→	}
352→	logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
353→	if err != nil {
354→		t.Fatalf("Failed to store log blob: %v", err)
355→	}
356→
357→	// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
358→	shardedPath := checkpointID.Path()
359→	checkpointIDStr := checkpointID.String()
360→
361→	// Create checkpoint tree with metadata and transcript files
362→	// Entries must be sorted alphabetically
363→	checkpointTree := object.Tree{
364→		Entries: []object.TreeEntry{
365→			{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
366→			{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
367→		},
368→	}
369→	checkpointTreeObj := repo.Storer.NewEncodedObject()
370→	if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
371→		t.Fatalf("Failed to encode checkpoint tree: %v", err)
372→	}
373→	checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
374→	if err != nil {
375→		t.Fatalf("Failed to store checkpoint tree: %v", err)
376→	}
377→
378→	// Create inner shard tree (id[2:])
379→	innerTree := object.Tree{
380→		Entries: []object.TreeEntry{
381→			{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
382→		},
383→	}
384→	innerTreeObj := repo.Storer.NewEncodedObject()
385→	if err := innerTree.Encode(innerTreeObj); err != nil {
386→		t.Fatalf("Failed to encode inner tree: %v", err)
387→	}
388→	innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
389→	if err != nil {
390→		t.Fatalf("Failed to store inner tree: %v", err)
391→	}
392→
393→	// Get existing tree entries from parent
394→	parentTree, err := parentCommit.Tree()
395→	if err != nil {
396→		t.Fatalf("Failed to get parent tree: %v", err)
397→	}
398→
399→	// Build new root tree with shard bucket
400→	var rootEntries []object.TreeEntry
401→	for _, entry := range parentTree.Entries {
402→		if entry.Name != shardedPath[:2] {
403→			rootEntries = append(rootEntries, entry)
404→		}
405→	}
406→	rootEntries = append(rootEntries, object.TreeEntry{
407→		Name: checkpointIDStr[:2],
408→		Mode: filemode.Dir,
409→		Hash: innerTreeHash,
410→	})
411→
412→	rootTree := object.Tree{Entries: rootEntries}
413→	rootTreeObj := repo.Storer.NewEncodedObject()
414→	if err := rootTree.Encode(rootTreeObj); err != nil {
415→		t.Fatalf("Failed to encode root tree: %v", err)
416→	}
417→	rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
418→	if err != nil {
419→		t.Fatalf("Failed to store root tree: %v", err)
420→	}
421→
422→	// Create commit on metadata branch
423→	commit := &object.Commit{
424→		Author: object.Signature{
425→			Name:  "Test",
426→			Email: "test@example.com",
427→			When:  parentCommit.Author.When,
428→		},
429→		Committer: object.Signature{
430→			Name:  "Test",
431→			Email: "test@example.com",
432→			When:  parentCommit.Author.When,
433→		},
434→		Message:      "Add checkpoint metadata",
435→		TreeHash:     rootTreeHash,
436→		ParentHashes: []plumbing.Hash{parentCommit.Hash},
437→	}
438→	commitObj := repo.Storer.NewEncodedObject()
439→	if err := commit.Encode(commitObj); err != nil {
440→		t.Fatalf("Failed to encode commit: %v", err)
441→	}
442→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
443→	if err != nil {
444→		t.Fatalf("Failed to store commit: %v", err)
445→	}
446→
447→	// Update metadata branch ref
448→	newRef := plumbing.NewHashReference(refName, commitHash)
449→	if err := repo.Storer.SetReference(newRef); err != nil {
450→		t.Fatalf("Failed to update metadata branch: %v", err)
451→	}
452→
453→	return checkpointID
454→}
