  14→// clearGlobalHooksPath overrides any global core.hooksPath setting so that
  15→// test repos use their default .git/hooks directory. Setting the local value
  16→// takes precedence over the global one.
  17→func clearGlobalHooksPath(t *testing.T, repoDir string) {
  18→	t.Helper()
  19→	cmd := exec.CommandContext(context.Background(), "git", "config", "--local", "core.hooksPath", filepath.Join(repoDir, ".git", "hooks"))
  20→	cmd.Dir = repoDir
  21→	if err := cmd.Run(); err != nil {
  22→		t.Fatalf("failed to set local core.hooksPath: %v", err)
  23→	}
  24→}
