  26→// initHooksTestRepo creates a temporary git repository, changes to it, and clears
  27→// the repo root cache. Returns the repo directory path and the hooks directory path.
  28→func initHooksTestRepo(t *testing.T) (string, string) {
  29→	t.Helper()
  30→	tmpDir := t.TempDir()
  31→	t.Chdir(tmpDir)
  32→
  33→	ctx := context.Background()
  34→	cmd := exec.CommandContext(ctx, "git", "init")
  35→	cmd.Dir = tmpDir
  36→	if err := cmd.Run(); err != nil {
  37→		t.Fatalf("failed to init git repo: %v", err)
  38→	}
  39→	clearGlobalHooksPath(t, tmpDir)
  40→	paths.ClearWorktreeRootCache()
  41→
  42→	return tmpDir, filepath.Join(tmpDir, ".git", "hooks")
  43→}
