 62→func runResume(ctx context.Context, cmd *cobra.Command, branchName string, force bool) error {
 63→	w := cmd.OutOrStdout()
 64→	errW := cmd.ErrOrStderr()
 65→
 66→	// Check if we're already on this branch
 67→	currentBranch, err := GetCurrentBranch(ctx)
 68→	if err == nil && currentBranch == branchName {
 69→		// Already on the branch, skip checkout
 70→		return resumeFromCurrentBranch(ctx, w, errW, branchName, force)
 71→	}
 72→
 73→	// Check if branch exists locally
 74→	exists, err := BranchExistsLocally(ctx, branchName)
 75→	if err != nil {
 76→		return fmt.Errorf("failed to check branch: %w", err)
 77→	}
 78→
 79→	if !exists {
 80→		// Branch doesn't exist locally, check if it exists on remote
 81→		remoteExists, err := BranchExistsOnRemote(ctx, branchName)
 82→		if err != nil {
 83→			return fmt.Errorf("failed to check remote branch: %w", err)
 84→		}
 85→
 86→		if !remoteExists {
 87→			return fmt.Errorf("branch '%s' not found locally or on origin", branchName)
 88→		}
 89→
 90→		// Ask user if they want to fetch from remote
 91→		shouldFetch, err := promptFetchFromRemote(branchName)
 92→		if err != nil {
 93→			return err
 94→		}
 95→		if !shouldFetch {
 96→			return nil
 97→		}
 98→
 99→		// Fetch and checkout the remote branch
100→		fmt.Fprintf(w, "Fetching branch '%s' from origin...\n", branchName)
101→		if err := FetchAndCheckoutRemoteBranch(ctx, branchName); err != nil {
102→			fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
103→			return NewSilentError(errors.New("failed to checkout branch"))
104→		}
105→		fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
106→	} else {
107→		// Branch exists locally, check for uncommitted changes before checkout
108→		hasChanges, err := HasUncommittedChanges(ctx)
109→		if err != nil {
110→			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
111→		}
112→		if hasChanges {
113→			return errors.New("you have uncommitted changes. Please commit or stash them first")
114→		}
115→
116→		// Checkout the branch
117→		if err := CheckoutBranch(ctx, branchName); err != nil {
118→			fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
119→			return NewSilentError(errors.New("failed to checkout branch"))
120→		}
121→		fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
122→	}
123→
124→	return resumeFromCurrentBranch(ctx, w, errW, branchName, force)
125→}
