225→// getMetadataTree returns the metadata branch tree, trying a treeless fetch
226→// first to ensure local data is up-to-date, then falling back to local,
227→// then full fetch, then remote tree directly.
228→func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
229→	// Always try treeless fetch first to ensure local branch is up-to-date
230→	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
231→		metadataTree, err := strategy.GetMetadataBranchTree(repo)
232→		if err == nil {
233→			return metadataTree, nil
234→		}
235→	}
236→
237→	// Try local (may have been set by a prior fetch or push)
238→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
239→	if err == nil {
240→		return metadataTree, nil
241→	}
242→
243→	// Fallback: full fetch from remote
244→	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
245→		metadataTree, err = strategy.GetMetadataBranchTree(repo)
246→		if err == nil {
247→			return metadataTree, nil
248→		}
249→	}
250→
251→	// Try remote tree directly
252→	remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
253→	if remoteErr != nil {
254→		return nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
255→	}
256→	return remoteTree, nil
257→}
258→
259→// ensureTranscriptBlobs checks which transcript blobs for a checkpoint are
260→// present in the local object store (via go-git) and fetches any missing
261→// ones from the remote (via git CLI).
262→// This enables the treeless-fetch optimization: tree objects are fetched first,
263→// then only the specific full.jsonl blobs needed for resume are downloaded.
264→func ensureTranscriptBlobs(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
265→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
266→	if err != nil {
267→		// If we can't get the tree, blobs can't be checked — caller will handle the error
268→		return nil //nolint:nilerr // Tree unavailable means no sparse fetch possible
269→	}
270→
271→	refs, err := checkpoint.CollectTranscriptBlobHashes(metadataTree, checkpointID)
272→	if err != nil {
273→		// Tree navigation failed — not fatal, ReadSessionContent will fail with a clear error
274→		return nil //nolint:nilerr // Best-effort blob prefetch
275→	}
276→
277→	resolver := checkpoint.NewBlobResolver(repo.Storer)
278→	var missing []plumbing.Hash
279→	for _, ref := range refs {
280→		if !resolver.HasBlob(ref.Hash) {
281→			missing = append(missing, ref.Hash)
282→		}
283→	}
284→	if len(missing) == 0 {
285→		return nil
286→	}
287→
288→	return FetchBlobsByHash(ctx, missing)
289→}
