442→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
443→// and automatically fetches it if available.
444→func checkRemoteMetadata(ctx context.Context, w, errW io.Writer, repo *git.Repository, checkpointID id.CheckpointID) error {
445→	// Try to get remote metadata branch tree
446→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
447→	if err != nil {
448→		fmt.Fprintf(w, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
449→		fmt.Fprintf(w, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
450→		return nil //nolint:nilerr // Informational message, not a fatal error
451→	}
452→
453→	// Check if the checkpoint exists on the remote
454→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
455→	if err != nil {
456→		fmt.Fprintf(w, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
457→		return nil //nolint:nilerr // Informational message, not a fatal error
458→	}
459→
460→	// Metadata exists on remote but not locally - fetch it automatically
461→	fmt.Fprintf(w, "Fetching session metadata from origin...\n")
462→	if err := FetchMetadataBranch(ctx); err != nil {
463→		fmt.Fprintf(errW, "Error: failed to fetch metadata: %v\n", err)
464→		fmt.Fprintf(errW, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
465→		return NewSilentError(errors.New("failed to fetch metadata"))
466→	}
467→
468→	// Now resume the session with the fetched metadata
469→	return resumeSession(ctx, w, errW, metadata, false)
470→}
471→
472→// resumeSession restores and displays the resume command for a specific session.
473→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
474→// If force is false, prompts for confirmation when local logs have newer timestamps.
475→// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
476→// and to support both local and remote metadata trees.
477→func resumeSession(ctx context.Context, w, errW io.Writer, metadata *strategy.CheckpointInfo, force bool) error {
478→	checkpointID := metadata.CheckpointID
479→	sessionID := metadata.SessionID
480→
481→	// Resolve agent from checkpoint metadata (same as rewind)
482→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
483→	if err != nil {
484→		return fmt.Errorf("failed to resolve agent: %w", err)
485→	}
486→
487→	// Initialize logging context with agent
488→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
489→
490→	logging.Debug(logCtx, "resume session started",
491→		slog.String("checkpoint_id", checkpointID.String()),
492→		slog.String("session_id", sessionID),
493→	)
494→
495→	// Get worktree root for session directory lookup
496→	repoRoot, err := paths.WorktreeRoot(ctx)
497→	if err != nil {
498→		return fmt.Errorf("failed to get worktree root: %w", err)
499→	}
500→
501→	sessionDir, err := ag.GetSessionDir(repoRoot)
502→	if err != nil {
503→		return fmt.Errorf("failed to determine session directory: %w", err)
504→	}
505→
506→	// Create directory if it doesn't exist
507→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
508→		return fmt.Errorf("failed to create session directory: %w", err)
509→	}
510→
511→	// Get strategy and restore sessions using full checkpoint data
512→	strat := GetStrategy(ctx)
513→
514→	// Ensure transcript blobs are available locally before RestoreLogsOnly reads them.
515→	// After a treeless fetch, tree objects are present but full.jsonl blobs may not be.
516→	// This fetches only the specific blobs needed for this checkpoint.
517→	repo, repoErr := openRepository(ctx)
518→	if repoErr == nil {
519→		if blobErr := ensureTranscriptBlobs(ctx, repo, checkpointID); blobErr != nil {
520→			logging.Warn(logCtx, "failed to ensure transcript blobs, restore may fail",
521→				slog.String("error", blobErr.Error()),
522→			)
523→		}
524→	}
525→
526→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
527→	// Create a logs-only rewind point with Agent populated (same as rewind)
528→	point := strategy.RewindPoint{
529→		IsLogsOnly:   true,
530→		CheckpointID: checkpointID,
531→		Agent:        metadata.Agent,
532→	}
533→
534→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
535→	if restoreErr != nil || len(sessions) == 0 {
536→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
537→		return resumeSingleSession(ctx, w, errW, ag, sessionID, checkpointID, repoRoot, force)
538→	}
539→
540→	logging.Debug(logCtx, "resume session completed",
541→		slog.String("checkpoint_id", checkpointID.String()),
542→		slog.Int("session_count", len(sessions)),
543→	)
544→
545→	return displayRestoredSessions(w, sessions)
546→}
