548→// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
549→func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
550→	sort.SliceStable(sessions, func(i, j int) bool {
551→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
552→	})
553→
554→	if len(sessions) > 1 {
555→		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue, run:\n", len(sessions))
556→	} else if len(sessions) == 1 {
557→		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
558→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
559→	}
560→
561→	isMulti := len(sessions) > 1
562→	for i, sess := range sessions {
563→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
564→		if err != nil {
565→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
566→		}
567→		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
568→	}
569→
570→	return nil
571→}
