573→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
574→// Always overwrites existing session logs to ensure consistency with checkpoint state.
575→// If force is false, prompts for confirmation when local log has newer timestamps.
576→func resumeSingleSession(ctx context.Context, w, errW io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
577→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
578→	if err != nil {
579→		return fmt.Errorf("failed to resolve transcript path: %w", err)
580→	}
581→
582→	if checkpointID.IsEmpty() {
583→		logging.Debug(ctx, "resume session: empty checkpoint ID",
584→			slog.String("checkpoint_id", checkpointID.String()),
585→		)
586→		fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
587→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
588→		fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
589→		return nil
590→	}
591→
592→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
593→	if err != nil {
594→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
595→			logging.Debug(ctx, "resume session completed (no metadata)",
596→				slog.String("checkpoint_id", checkpointID.String()),
597→				slog.String("session_id", sessionID),
598→			)
599→			fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
600→			fmt.Fprintf(w, "\nTo continue this session, run:\n")
601→			fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
602→			return nil
603→		}
604→		logging.Error(ctx, "resume session failed",
605→			slog.String("checkpoint_id", checkpointID.String()),
606→			slog.String("session_id", sessionID),
607→			slog.String("error", err.Error()),
608→		)
609→		return fmt.Errorf("failed to get session log: %w", err)
610→	}
611→
612→	// Check if local file has newer timestamps than checkpoint
613→	if !force {
614→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
615→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
616→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
617→
618→		if status == strategy.StatusLocalNewer {
619→			sessions := []strategy.SessionRestoreInfo{{
620→				SessionID:      sessionID,
621→				Status:         status,
622→				LocalTime:      localTime,
623→				CheckpointTime: checkpointTime,
624→			}}
625→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(errW, sessions)
626→			if promptErr != nil {
627→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
628→			}
629→			if !shouldOverwrite {
630→				fmt.Fprintf(w, "Resume cancelled. Local session log preserved.\n")
631→				return nil
632→			}
633→		}
634→	}
635→
636→	// Ensure parent directory exists
637→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
638→		return fmt.Errorf("failed to create session directory: %w", err)
639→	}
640→
641→	agentSession := &agent.AgentSession{
642→		SessionID:  sessionID,
643→		AgentName:  ag.Name(),
644→		RepoPath:   repoRoot,
645→		SessionRef: sessionLogPath,
646→		NativeData: logContent,
647→	}
648→
649→	// Write the session using the agent's WriteSession method
650→	if err := ag.WriteSession(ctx, agentSession); err != nil {
651→		logging.Error(ctx, "resume session failed during write",
652→			slog.String("checkpoint_id", checkpointID.String()),
653→			slog.String("session_id", sessionID),
654→			slog.String("error", err.Error()),
655→		)
656→		return fmt.Errorf("failed to write session: %w", err)
657→	}
658→
659→	logging.Debug(ctx, "resume session completed",
660→		slog.String("checkpoint_id", checkpointID.String()),
661→		slog.String("session_id", sessionID),
662→	)
663→
664→	fmt.Fprintf(w, "✓ Session restored to: %s\n", sessionLogPath)
665→	fmt.Fprintf(w, "  Session: %s\n", sessionID)
666→	fmt.Fprintf(w, "\nTo continue this session, run:\n")
667→	fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
668→
669→	return nil
670→}
