456→// TestResolveLatestCheckpoint verifies that resolveLatestCheckpoint returns the
457→// checkpoint with the newest CreatedAt, regardless of trailer order.
458→func TestResolveLatestCheckpoint(t *testing.T) {
459→	tmpDir := t.TempDir()
460→	t.Chdir(tmpDir)
461→
462→	repo, _, _ := setupResumeTestRepo(t, tmpDir, false)
463→
464→	// Create checkpoints with different timestamps.
465→	// Simulate git CLI squash merge order: newest first in the commit message.
466→	t1 := time.Date(2025, 1, 1, 10, 0, 0, 0, time.UTC) // oldest
467→	t2 := time.Date(2025, 1, 1, 11, 0, 0, 0, time.UTC)
468→	t3 := time.Date(2025, 1, 1, 12, 0, 0, 0, time.UTC) // newest
469→
470→	cpID1 := createCheckpointOnMetadataBranchFull(t, repo, "session-oldest", id.MustCheckpointID("aaa111bbb222"), t1)
471→	cpID2 := createCheckpointOnMetadataBranchFull(t, repo, "session-middle", id.MustCheckpointID("ccc333ddd444"), t2)
472→	cpID3 := createCheckpointOnMetadataBranchFull(t, repo, "session-newest", id.MustCheckpointID("eee555fff666"), t3)
473→
474→	// Pass checkpoint IDs in reverse chronological order (newest first),
475→	// simulating git CLI squash merge trailer order.
476→	reverseOrderIDs := []id.CheckpointID{cpID3, cpID2, cpID1}
477→	latest, tree, _, err := resolveLatestCheckpoint(context.Background(), reverseOrderIDs)
478→	if err != nil {
479→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
480→	}
481→
482→	// Should return the newest checkpoint regardless of input order
483→	if latest.String() != cpID3.String() {
484→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest, cpID3)
485→	}
486→
487→	// Should return a non-nil tree for reuse
488→	if tree == nil {
489→		t.Error("resolveLatestCheckpoint() returned nil tree")
490→	}
491→
492→	// Also verify with chronological order
493→	chronologicalIDs := []id.CheckpointID{cpID1, cpID2, cpID3}
494→	latest2, _, _, err := resolveLatestCheckpoint(context.Background(), chronologicalIDs)
495→	if err != nil {
496→		t.Fatalf("resolveLatestCheckpoint() error = %v", err)
497→	}
498→	if latest2.String() != cpID3.String() {
499→		t.Errorf("resolveLatestCheckpoint() = %s, want newest %s", latest2, cpID3)
500→	}
501→}
