 17→// IsAccessibleMode returns true if accessibility mode should be enabled.
 18→// This checks the ACCESSIBLE environment variable.
 19→// Set ACCESSIBLE=1 (or any non-empty value) to enable accessible mode,
 20→// which uses simpler prompts that work better with screen readers.
 21→func IsAccessibleMode() bool {
 22→	return os.Getenv("ACCESSIBLE") != ""
 23→}
 24→
 25→// entireTheme returns the Dracula theme for consistent styling.
 26→func entireTheme() *huh.Theme {
 27→	return huh.ThemeDracula()
 28→}
 29→
 30→// NewAccessibleForm creates a new huh form with accessibility mode
 31→// enabled if the ACCESSIBLE environment variable is set.
 32→// Note: WithAccessible() is only available on forms, not individual fields.
 33→// Always wrap confirmations and other prompts in a form to enable accessibility.
 34→func NewAccessibleForm(groups ...*huh.Group) *huh.Form {
 35→	form := huh.NewForm(groups...).WithTheme(entireTheme())
 36→	if IsAccessibleMode() {
 37→		form = form.WithAccessible(true)
 38→	}
 39→	return form
 40→}
