 42→// handleFormCancellation handles cancellation from huh form prompts.
 43→// If err is a user abort (Ctrl+C), it prints "[action] cancelled." to w and returns nil.
 44→// Otherwise it returns the error as-is.
 45→func handleFormCancellation(w io.Writer, action string, err error) error {
 46→	if errors.Is(err, huh.ErrUserAborted) {
 47→		fmt.Fprintf(w, "%s cancelled.\n", action)
 48→		return nil
 49→	}
 50→	return err
 51→}
 52→
 53→// printSessionCommand writes a single session resume command line to w.
 54→// It appends a "(most recent)" label to the last entry in a multi-session list,
 55→// and a "# prompt" comment when a prompt is available.
 56→func printSessionCommand(w io.Writer, resumeCmd, prompt string, isMulti, isLast bool) {
 57→	comment := ""
 58→	if isMulti && isLast {
 59→		if prompt != "" {
 60→			comment = fmt.Sprintf("  # %s (most recent)", prompt)
 61→		} else {
 62→			comment = "  # (most recent)"
 63→		}
 64→	} else if prompt != "" {
 65→		comment = "  # " + prompt
 66→	}
 67→	fmt.Fprintf(w, "  %s%s\n", resumeCmd, comment)
 68→}
